    "batch-radiology-final-430-q014": {"review": {"answers": ["B"], "confidence": "supported", "basis": "lecture", "explanation": "Technetium-99m sestamibi can persist in hyperfunctioning parathyroid tissue on delayed imaging. It helps localize abnormal glands before surgery after biochemical diagnosis.", "evidence": {"title": "L22 (CBL) Endocrine Radiology", "sourceId": "1WddjUab6yD4K9z_VIUXWa1_Micvsa2jM", "page": 12, "unit": "page", "quote": "Most commonly used for parathyroid imaging", "url": "https://drive.google.com/file/d/1WddjUab6yD4K9z_VIUXWa1_Micvsa2jM/view#page=12", "cohortLabel": "MED444 teaching notes", "sourceSha256": "85399286a691d14733fdea568858d5920f5e5d66a8e9bf667553160752ac1f34", "relation": "direct", "image": "lecture-media/radiology-final-review/1WddjUab6yD4K9z_VIUXWa1_Micvsa2jM-p12.jpg"}, "references": [{"title": "EANM · Guidelines for Parathyroid Imaging", "url": "https://pubmed.ncbi.nlm.nih.gov/33839893/"}]}},
    "batch-radiology-final-434-q008": {"review": {"answers": ["B"], "confidence": "supported", "basis": "concept", "explanation": "The circumscribed area contains a mixture of radiolucent fat and denser fibroglandular tissue, giving a breast-within-a-breast appearance. That mixed composition favors a hamartoma over a homogeneous lipoma.", "references": [{"title": "Original Case Report · Breast-within-a-Breast Sign", "url": "https://pubmed.ncbi.nlm.nih.gov/26663968/"}]}},
    "batch-radiology-final-434-q009": {"review": {"answers": ["C"], "confidence": "supported", "basis": "lecture", "explanation": "Multiple periventricular hyperintense white-matter lesions in a young adult suggest demyelination. A formal multiple sclerosis diagnosis also depends on lesion distribution, timing and alternative explanations.", "evidence": {"title": "L26 (CBL) CNS Radiology  (1)", "sourceId": "1G45Gk2A6tw8TkfUa2k1fcqXXaunq2L5t", "page": 13, "unit": "page", "quote": "multiple lesions in the periventricular and subcortical white matter", "url": "https://drive.google.com/file/d/1G45Gk2A6tw8TkfUa2k1fcqXXaunq2L5t/view#page=13", "cohortLabel": "MED444 teaching notes", "sourceSha256": "08d66f0fbdba78cf48e05ba1ce7a4a30223dd76f857aee28e1a83cc00e4b1002", "relation": "direct", "image": "lecture-media/radiology-final-review/1G45Gk2A6tw8TkfUa2k1fcqXXaunq2L5t-p13.jpg"}}},
    "batch-radiology-final-434-q010": {"review": {"answers": ["A"], "confidence": "supported", "basis": "concept", "explanation": "The low-attenuation region involves the medial occipital lobe, the cortical territory of the posterior cerebral artery. This distribution is more specific than the overall size of the abnormality.", "references": [{"title": "ACR · Orbits, Vision, and Visual Loss", "url": "https://acsearch.acr.org/list/TopicNarrativePdf?topicId=361"}]}},
    "batch-radiology-final-434-q011": {"review": {"answers": ["C"], "confidence": "supported", "basis": "lecture", "explanation": "The dense right-sided extra-axial collection bulges inward in a lens shape and compresses the adjacent hemisphere. That shape favors an epidural hematoma.", "evidence": {"title": "L26 (CBL) CNS Radiology  (1)", "sourceId": "1G45Gk2A6tw8TkfUa2k1fcqXXaunq2L5t", "page": 6, "unit": "page", "quote": "Acute epidural hematoma (lens shape and don’t cross the suture lines)", "url": "https://drive.google.com/file/d/1G45Gk2A6tw8TkfUa2k1fcqXXaunq2L5t/view#page=6", "cohortLabel": "MED444 teaching notes", "sourceSha256": "08d66f0fbdba78cf48e05ba1ce7a4a30223dd76f857aee28e1a83cc00e4b1002", "relation": "direct", "image": "lecture-media/radiology-final-review/1G45Gk2A6tw8TkfUa2k1fcqXXaunq2L5t-p06.jpg"}}},
    "batch-radiology-final-434-q012": {"review": {"answers": ["C"], "confidence": "supported", "basis": "lecture", "explanation": "The figure plots metabolite peaks such as choline, creatine and NAA against chemical shift in parts per million. It is an MR spectrum.", "evidence": {"title": "L26 (CBL) CNS Radiology  (1)", "sourceId": "1G45Gk2A6tw8TkfUa2k1fcqXXaunq2L5t", "page": 8, "unit": "page", "quote": "MR spectroscopy", "url": "https://drive.google.com/file/d/1G45Gk2A6tw8TkfUa2k1fcqXXaunq2L5t/view#page=8", "cohortLabel": "MED444 teaching notes", "sourceSha256": "08d66f0fbdba78cf48e05ba1ce7a4a30223dd76f857aee28e1a83cc00e4b1002", "relation": "direct", "image": "lecture-media/radiology-final-review/1G45Gk2A6tw8TkfUa2k1fcqXXaunq2L5t-p08.jpg"}}},
    "batch-radiology-final-434-q013": {"review": {"answers": ["A"], "confidence": "supported", "basis": "lecture", "explanation": "Bright blood outlines the basal cisterns and extends along the subarachnoid spaces. Traumatic subarachnoid blood follows these spaces rather than forming a lens or a crescent along the skull.", "evidence": {"title": "L26 (CBL) CNS Radiology  (1)", "sourceId": "1G45Gk2A6tw8TkfUa2k1fcqXXaunq2L5t", "page": 18, "unit": "page", "quote": "Subarachnoid hemorrhage. Along salci", "url": "https://drive.google.com/file/d/1G45Gk2A6tw8TkfUa2k1fcqXXaunq2L5t/view#page=18", "cohortLabel": "MED444 teaching notes", "sourceSha256": "08d66f0fbdba78cf48e05ba1ce7a4a30223dd76f857aee28e1a83cc00e4b1002", "relation": "direct", "image": "lecture-media/radiology-final-review/1G45Gk2A6tw8TkfUa2k1fcqXXaunq2L5t-p18.jpg"}}},
    "batch-radiology-final-434-q014": {"review": {"answers": ["A"], "confidence": "supported", "basis": "concept", "explanation": "The skull has multiple rounded punched-out lucencies. This pattern is classic for myeloma in an adult, although imaging needs laboratory and clinical correlation.", "evidence": {"title": "L18 Radiology of bone infection and tumors", "sourceId": "1Wv1dwdR9B5IVuM84o9xclNg43mhdE_U4", "page": 6, "unit": "page", "quote": "Adult, Elderly lymphoma, myeloma, and metastasis are the most common.", "url": "https://drive.google.com/file/d/1Wv1dwdR9B5IVuM84o9xclNg43mhdE_U4/view#page=6", "cohortLabel": "MED444 teaching notes", "sourceSha256": "c21f4e1e1c6ffad65f8380580f98beef81ebd659540e63aa4854a9421f86b325", "relation": "background", "image": "lecture-media/radiology-final-review/1Wv1dwdR9B5IVuM84o9xclNg43mhdE_U4-p06.jpg"}, "references": [{"title": "International Myeloma Working Group · Consensus on imaging", "url": "https://pubmed.ncbi.nlm.nih.gov/31162104/"}]}},
