    "batch-radiology-final-434-q015": {"review": {"answers": ["C"], "confidence": "supported", "basis": "concept", "explanation": "The bright focus on diffusion-weighted MRI, in a patient with a sudden focal deficit, favors acute ischemia. Corresponding low ADC confirms restriction and helps distinguish it from T2 shine-through.", "references": [{"title": "ACR · Cerebrovascular Disease", "url": "https://acsearch.acr.org/docs/69478/Narrative"}]}},
    "batch-radiology-final-433-q001": {"review": {"answers": ["D"], "confidence": "supported", "basis": "lecture", "explanation": "Vertebral body comminution and posterior wall involvement indicate a burst pattern from axial compression. The retropulsed fragment separates this pattern from an isolated anterior wedge fracture.", "evidence": {"title": "L25 Radiology of the spinal diseases (1)", "sourceId": "1O---4sciuCkAdD_SuPyf86FxzbEn57aC", "page": 13, "unit": "page", "quote": "disruption of the posterior vertebral body cortex with retropulsion", "url": "https://drive.google.com/file/d/1O---4sciuCkAdD_SuPyf86FxzbEn57aC/view#page=13", "cohortLabel": "MED444 teaching notes", "sourceSha256": "6bd90403fc962fdcde7322d44b45c05bcdc7d5148318c3d89fee28eb2e14ad8c", "relation": "direct", "image": "lecture-media/radiology-final-review/1O---4sciuCkAdD_SuPyf86FxzbEn57aC-p13.jpg"}}},
    "batch-radiology-final-433-q002": {"review": {"answers": ["A"], "confidence": "supported", "basis": "lecture", "explanation": "The lateral view shows a C2 injury with forward translation relative to C3, consistent with a hangman's fracture. Hyperextension with axial loading or distraction is the classic mechanism.", "evidence": {"title": "L25 Radiology of the spinal diseases (1)", "sourceId": "1O---4sciuCkAdD_SuPyf86FxzbEn57aC", "page": 23, "unit": "page", "quote": "due to hyperextension (e.g., RTA)", "url": "https://drive.google.com/file/d/1O---4sciuCkAdD_SuPyf86FxzbEn57aC/view#page=23", "cohortLabel": "MED444 teaching notes", "sourceSha256": "6bd90403fc962fdcde7322d44b45c05bcdc7d5148318c3d89fee28eb2e14ad8c", "relation": "direct", "image": "lecture-media/radiology-final-review/1O---4sciuCkAdD_SuPyf86FxzbEn57aC-p23.jpg"}}},
