    "batch-radiology-final-433-q003": {"review": {"answers": ["D"], "confidence": "supported", "basis": "lecture", "explanation": "Chronic tophaceous gout produces lobulated periarticular soft-tissue masses. Adjacent punched-out erosions with overhanging margins strengthen that interpretation.", "evidence": {"title": "L17 Radiology of rheumatic diseases (1)", "sourceId": "13bncDX_nhFu9YXIgJlDRV7dVmd7cvgsg", "page": 13, "unit": "page", "quote": "Gouty Arthritis Radiological findings", "url": "https://drive.google.com/file/d/13bncDX_nhFu9YXIgJlDRV7dVmd7cvgsg/view#page=13", "cohortLabel": "MED444 teaching notes", "sourceSha256": "716568ce015afbea431d6c172338e9edf575cf199ebd842c1e630cce9eb02213", "relation": "direct", "image": "lecture-media/radiology-final-review/13bncDX_nhFu9YXIgJlDRV7dVmd7cvgsg-p13.jpg"}}},
