    "batch-radiology-final-433-q004": {"review": {"answers": ["A"], "confidence": "supported", "basis": "concept", "explanation": "Salter–Harris injuries involve the growth plate. Type V is a crush injury of the physis and may only be recognized later when growth arrest develops.", "references": [{"title": "Pediatric physeal injuries and the Salter–Harris classification", "url": "https://pubmed.ncbi.nlm.nih.gov/27206505/"}]}},
    "batch-radiology-final-430-q005": {"review": {"answers": ["D"], "confidence": "supported", "basis": "concept", "explanation": "Salter–Harris injuries involve the growth plate. Type V is a crush injury of the physis and may only be recognized later when growth arrest develops.", "references": [{"title": "Pediatric physeal injuries and the Salter–Harris classification", "url": "https://pubmed.ncbi.nlm.nih.gov/27206505/"}]}},
    "batch-radiology-final-433-q006": {"review": {"answers": ["C"], "confidence": "supported", "basis": "concept", "explanation": "Plain radiography is the usual first study for many suspected bone and joint abnormalities. MRI, ultrasound or CT can be preferred when the clinical concern is marrow, soft tissue, or complex anatomy.", "references": [{"title": "AAOS · Forearm fractures in children", "url": "https://orthoinfo.aaos.org/en/diseases--conditions/forearm-fractures-in-children/"}, {"title": "ACR · Acute Hand and Wrist Trauma", "url": "https://acsearch.acr.org/docs/69418/Narrative"}]}},
    "batch-radiology-final-433-q007": {"review": {"answers": [], "confidence": "unresolved", "basis": "concept", "explanation": "A child's open physis is a site of vulnerability. Once it closes, a ligament or tendon can fail in an injury, but no single tissue is weakest in every adult musculoskeletal structure or mechanism.", "references": [{"title": "Pediatric physeal injuries and the Salter–Harris classification", "url": "https://pubmed.ncbi.nlm.nih.gov/27206505/"}]}, "ungradedReason": "The original question or options do not establish one usable answer."},
    "batch-radiology-final-433-q008": {"review": {"answers": ["C"], "confidence": "supported", "basis": "lecture", "explanation": "The thyroid bed has very little tracer uptake while salivary activity remains visible. With thyrotoxicosis, this pattern favors destructive thyroiditis over Graves disease or a functioning toxic nodule.", "evidence": {"title": "L22 (CBL) Endocrine Radiology", "sourceId": "1WddjUab6yD4K9z_VIUXWa1_Micvsa2jM", "page": 5, "unit": "page", "quote": "Parenchymal Destruction: Acute, Subacute Thyroiditis", "url": "https://drive.google.com/file/d/1WddjUab6yD4K9z_VIUXWa1_Micvsa2jM/view#page=5", "cohortLabel": "MED444 teaching notes", "sourceSha256": "85399286a691d14733fdea568858d5920f5e5d66a8e9bf667553160752ac1f34", "relation": "direct", "image": "lecture-media/radiology-final-review/1WddjUab6yD4K9z_VIUXWa1_Micvsa2jM-p05.jpg"}, "references": [{"title": "SNMMI and EANM · Thyroid scintigraphy and radioiodine uptake", "url": "https://pubmed.ncbi.nlm.nih.gov/31392371/"}]}},
    "batch-radiology-final-431-q015": {"review": {"answers": ["C"], "confidence": "supported", "basis": "lecture", "explanation": "The thyroid bed has very little tracer uptake while salivary activity remains visible. With thyrotoxicosis, this pattern favors destructive thyroiditis over Graves disease or a functioning toxic nodule.", "evidence": {"title": "L22 (CBL) Endocrine Radiology", "sourceId": "1WddjUab6yD4K9z_VIUXWa1_Micvsa2jM", "page": 5, "unit": "page", "quote": "Parenchymal Destruction: Acute, Subacute Thyroiditis", "url": "https://drive.google.com/file/d/1WddjUab6yD4K9z_VIUXWa1_Micvsa2jM/view#page=5", "cohortLabel": "MED444 teaching notes", "sourceSha256": "85399286a691d14733fdea568858d5920f5e5d66a8e9bf667553160752ac1f34", "relation": "direct", "image": "lecture-media/radiology-final-review/1WddjUab6yD4K9z_VIUXWa1_Micvsa2jM-p05.jpg"}, "references": [{"title": "SNMMI and EANM · Thyroid scintigraphy and radioiodine uptake", "url": "https://pubmed.ncbi.nlm.nih.gov/31392371/"}]}},
    "batch-radiology-final-433-q009": {"review": {"answers": ["B"], "confidence": "supported", "basis": "concept", "explanation": "After thyroidectomy for papillary thyroid carcinoma, multifocal tracer uptake distributed across both lung fields is suspicious for iodine-avid pulmonary metastases. SPECT/CT can help confirm the location if planar uptake is indeterminate.", "references": [{"title": "SNMMI and EANM · Radioiodine in differentiated thyroid cancer", "url": "https://pubmed.ncbi.nlm.nih.gov/35649660/"}]}},
    "batch-radiology-final-431-q013": {"review": {"answers": ["B"], "confidence": "supported", "basis": "concept", "explanation": "After thyroidectomy for papillary thyroid carcinoma, multifocal tracer uptake distributed across both lung fields is suspicious for iodine-avid pulmonary metastases. SPECT/CT can help confirm the location if planar uptake is indeterminate.", "references": [{"title": "SNMMI and EANM · Radioiodine in differentiated thyroid cancer", "url": "https://pubmed.ncbi.nlm.nih.gov/35649660/"}]}},
    "batch-radiology-final-433-q011": {"review": {"answers": ["C"], "confidence": "supported", "basis": "lecture", "explanation": "The physical half-life of iodine-123 is approximately 13.2 hours. It is used for diagnostic imaging, whereas iodine-131 has a much longer half-life and can deliver beta therapy.", "evidence": {"title": "L22 (CBL) Endocrine Radiology", "sourceId": "1WddjUab6yD4K9z_VIUXWa1_Micvsa2jM", "page": 3, "unit": "page", "quote": "13.2 hrs", "url": "https://drive.google.com/file/d/1WddjUab6yD4K9z_VIUXWa1_Micvsa2jM/view#page=3", "cohortLabel": "MED444 teaching notes", "sourceSha256": "85399286a691d14733fdea568858d5920f5e5d66a8e9bf667553160752ac1f34", "relation": "direct", "image": "lecture-media/radiology-final-review/1WddjUab6yD4K9z_VIUXWa1_Micvsa2jM-p03.jpg"}}},
    "batch-radiology-final-433-q012": {"review": {"answers": ["A"], "confidence": "supported", "basis": "concept", "explanation": "The breasts hang into the dedicated coil while the patient lies prone. A standard breast MRI for tumor extent uses IV gadolinium to assess enhancement.", "references": [{"title": "ACR · Breast MRI with Contrast", "url": "https://www.acr.org/-/media/acr/files/practice-parameters/mr-contrast-breast.pdf"}]}},
    "batch-radiology-final-433-q014": {"review": {"answers": ["C"], "confidence": "supported", "basis": "concept", "explanation": "The breasts hang into the dedicated coil while the patient lies prone. A standard breast MRI for tumor extent uses IV gadolinium to assess enhancement.", "references": [{"title": "ACR · Breast MRI with Contrast", "url": "https://www.acr.org/-/media/acr/files/practice-parameters/mr-contrast-breast.pdf"}]}},
