    "batch-radiology-final-430-q006": {"review": {"answers": ["A"], "confidence": "supported", "basis": "concept", "explanation": "The breasts hang into the dedicated coil while the patient lies prone. A standard breast MRI for tumor extent uses IV gadolinium to assess enhancement.", "references": [{"title": "ACR · Breast MRI with Contrast", "url": "https://www.acr.org/-/media/acr/files/practice-parameters/mr-contrast-breast.pdf"}]}},
    "batch-radiology-final-433-q015": {"review": {"answers": ["D"], "confidence": "supported", "basis": "concept", "explanation": "Therapeutic iodine-131 requires stopping breastfeeding in advance. Breastfeeding should not resume for the current child after therapy. This restriction does not rule out breastfeeding a future child.", "references": [{"title": "American Thyroid Association · Radioactive Iodine", "url": "https://www.thyroid.org/radioactive-iodine/"}]}},
    "batch-radiology-final-433-q016": {"review": {"answers": ["B"], "confidence": "supported", "basis": "lecture", "explanation": "Radiating spicules at the edge of a mammographic mass increase suspicion for malignancy. Other findings such as a surgical scar or radial scar may mimic this appearance, so suspicious lesions require appropriate work-up.", "evidence": {"title": "L20 Radiology of the breast", "sourceId": "1LErhZCzNzkgg-Zw7doxjMaKyCW4hZXMO", "page": 13, "unit": "page", "quote": "Indistinct, Obscured, Microlobulated, Spiculated", "url": "https://drive.google.com/file/d/1LErhZCzNzkgg-Zw7doxjMaKyCW4hZXMO/view#page=13", "cohortLabel": "MED444 teaching notes", "sourceSha256": "c1dd13cded1029afc0edf9998fb84de8d41074d629b7c49cec5aa56318dfb037", "relation": "direct", "image": "lecture-media/radiology-final-review/1LErhZCzNzkgg-Zw7doxjMaKyCW4hZXMO-p13.jpg"}}},
    "batch-radiology-final-433-q017": {"review": {"answers": ["D"], "confidence": "supported", "basis": "concept", "explanation": "When a diagnostic whole-body scan uses endogenous TSH stimulation, withholding levothyroxine for about three to four weeks raises TSH. Four weeks matches the traditional protocol listed here. Recombinant TSH permits other preparation protocols.", "references": [{"title": "SNMMI and EANM · Radioiodine in differentiated thyroid cancer", "url": "https://pubmed.ncbi.nlm.nih.gov/35649660/"}]}},
    "batch-radiology-final-433-q019": {"review": {"answers": ["C"], "confidence": "supported", "basis": "concept", "explanation": "Chest or body CT can evaluate distant spread, such as lung or liver metastases, when systemic staging is indicated. Dedicated breast imaging is used to evaluate and characterize the primary lesion.", "references": [{"title": "ACR · Breast MRI with Contrast", "url": "https://www.acr.org/-/media/acr/files/practice-parameters/mr-contrast-breast.pdf"}]}},
    "batch-radiology-final-433-q021": {"review": {"answers": ["C"], "confidence": "supported", "basis": "lecture", "explanation": "Iodine-131 damages functioning thyroid tissue. Hypothyroidism is a common long-term result of treatment for Graves disease and is monitored with thyroid function tests.", "evidence": {"title": "L27 Nuclear medicine in oncology", "sourceId": "1gtqxnEr7g3JmC2779aHuQ6N4gBoYKL-p", "page": 6, "unit": "page", "quote": "Iodine-131 is a beta minus emitter", "url": "https://drive.google.com/file/d/1gtqxnEr7g3JmC2779aHuQ6N4gBoYKL-p/view#page=6", "cohortLabel": "MED444 teaching notes", "sourceSha256": "90265ab48690ae2a3001dc755fc42b4b00106c845ed66994de2269fd892ca446", "relation": "direct", "image": "lecture-media/radiology-final-review/1gtqxnEr7g3JmC2779aHuQ6N4gBoYKL-p-p06.jpg"}, "references": [{"title": "American Thyroid Association · Graves’ disease", "url": "https://www.thyroid.org/graves-disease/"}]}},
