    "batch-radiology-final-433-q023": {"review": {"answers": [], "confidence": "unresolved", "basis": "lecture", "explanation": "Iodine-131 emits beta particles and gamma photons. Beta emission provides the therapeutic effect, while gamma photons permit detection. The original key lists both and the stem does not specify a single purpose.", "evidence": {"title": "L27 Nuclear medicine in oncology", "sourceId": "1gtqxnEr7g3JmC2779aHuQ6N4gBoYKL-p", "page": 6, "unit": "page", "quote": "Iodine-131 is a beta minus emitter", "url": "https://drive.google.com/file/d/1gtqxnEr7g3JmC2779aHuQ6N4gBoYKL-p/view#page=6", "cohortLabel": "MED444 teaching notes", "sourceSha256": "90265ab48690ae2a3001dc755fc42b4b00106c845ed66994de2269fd892ca446", "relation": "direct", "image": "lecture-media/radiology-final-review/1gtqxnEr7g3JmC2779aHuQ6N4gBoYKL-p-p06.jpg"}, "references": [{"title": "L22 (CBL) Endocrine Radiology · MED444 PDF p. 3", "url": "https://drive.google.com/file/d/1WddjUab6yD4K9z_VIUXWa1_Micvsa2jM/view#page=3"}]}, "ungradedReason": "The original question or options do not establish one usable answer."},
