    "batch-radiology-final-433-q026": {"review": {"answers": ["A"], "confidence": "supported", "basis": "lecture", "explanation": "The cord expands over several levels, favoring an intramedullary tumor over a short demyelinating plaque. Astrocytoma is plausible among these options. Exact tumor typing also requires contrast features and tissue diagnosis.", "evidence": {"title": "L25 Radiology of the spinal diseases (1)", "sourceId": "1O---4sciuCkAdD_SuPyf86FxzbEn57aC", "page": 17, "unit": "page", "quote": "Ependymoma Astrocytoma Ependymoma Astrocytoma", "url": "https://drive.google.com/file/d/1O---4sciuCkAdD_SuPyf86FxzbEn57aC/view#page=17", "cohortLabel": "MED444 teaching notes", "sourceSha256": "6bd90403fc962fdcde7322d44b45c05bcdc7d5148318c3d89fee28eb2e14ad8c", "relation": "direct", "image": "lecture-media/radiology-final-review/1O---4sciuCkAdD_SuPyf86FxzbEn57aC-p17.jpg"}}},
