    "batch-radiology-final-433-q027": {"review": {"answers": [], "confidence": "unresolved", "basis": "lecture", "explanation": "The Gift key is subdural hemorrhage, but the original entry supplies no CT. The distinguishing clue would be a crescentic extra-axial collection that may cross sutures, stays constrained by dural reflections, and can compress the adjacent brain.", "evidence": {"title": "L26 (CBL) CNS Radiology  (1)", "sourceId": "1G45Gk2A6tw8TkfUa2k1fcqXXaunq2L5t", "page": 6, "unit": "page", "quote": "crescent shape and crosses the suture lines", "url": "https://drive.google.com/file/d/1G45Gk2A6tw8TkfUa2k1fcqXXaunq2L5t/view#page=6", "cohortLabel": "MED444 teaching notes", "sourceSha256": "08d66f0fbdba78cf48e05ba1ce7a4a30223dd76f857aee28e1a83cc00e4b1002", "relation": "direct", "image": "lecture-media/radiology-final-review/1G45Gk2A6tw8TkfUa2k1fcqXXaunq2L5t-p06.jpg"}}, "ungradedReason": "The original question or options do not establish one usable answer."},
    "batch-radiology-final-433-q029": {"review": {"answers": ["B"], "confidence": "supported", "basis": "lecture", "explanation": "A dense biconvex extra-axial collection with mass effect suggests an epidural hematoma. Head trauma can tear meningeal vessels and is the most likely cause among the listed options.", "evidence": {"title": "L26 (CBL) CNS Radiology  (1)", "sourceId": "1G45Gk2A6tw8TkfUa2k1fcqXXaunq2L5t", "page": 6, "unit": "page", "quote": "Acute epidural hematoma (lens shape and don’t cross the suture lines)", "url": "https://drive.google.com/file/d/1G45Gk2A6tw8TkfUa2k1fcqXXaunq2L5t/view#page=6", "cohortLabel": "MED444 teaching notes", "sourceSha256": "08d66f0fbdba78cf48e05ba1ce7a4a30223dd76f857aee28e1a83cc00e4b1002", "relation": "direct", "image": "lecture-media/radiology-final-review/1G45Gk2A6tw8TkfUa2k1fcqXXaunq2L5t-p06.jpg"}, "references": [{"title": "ACR · Head Trauma", "url": "https://acsearch.acr.org/docs/69481/Narrative"}]}},
    "batch-radiology-final-433-q030": {"review": {"answers": ["B"], "confidence": "supported", "basis": "lecture", "explanation": "A crescent-shaped hyperdense extra-axial collection extends along the cerebral convexity. That shape supports a subdural hematoma.", "evidence": {"title": "L26 (CBL) CNS Radiology  (1)", "sourceId": "1G45Gk2A6tw8TkfUa2k1fcqXXaunq2L5t", "page": 6, "unit": "page", "quote": "crescent shape and crosses the suture lines", "url": "https://drive.google.com/file/d/1G45Gk2A6tw8TkfUa2k1fcqXXaunq2L5t/view#page=6", "cohortLabel": "MED444 teaching notes", "sourceSha256": "08d66f0fbdba78cf48e05ba1ce7a4a30223dd76f857aee28e1a83cc00e4b1002", "relation": "direct", "image": "lecture-media/radiology-final-review/1G45Gk2A6tw8TkfUa2k1fcqXXaunq2L5t-p06.jpg"}}},
    "batch-radiology-final-431-q030": {"review": {"answers": ["B"], "confidence": "supported", "basis": "lecture", "explanation": "A crescent-shaped hyperdense extra-axial collection extends along the cerebral convexity. That shape supports a subdural hematoma.", "evidence": {"title": "L26 (CBL) CNS Radiology  (1)", "sourceId": "1G45Gk2A6tw8TkfUa2k1fcqXXaunq2L5t", "page": 6, "unit": "page", "quote": "crescent shape and crosses the suture lines", "url": "https://drive.google.com/file/d/1G45Gk2A6tw8TkfUa2k1fcqXXaunq2L5t/view#page=6", "cohortLabel": "MED444 teaching notes", "sourceSha256": "08d66f0fbdba78cf48e05ba1ce7a4a30223dd76f857aee28e1a83cc00e4b1002", "relation": "direct", "image": "lecture-media/radiology-final-review/1G45Gk2A6tw8TkfUa2k1fcqXXaunq2L5t-p06.jpg"}}},
    "batch-radiology-final-433-q031": {"review": {"answers": [], "confidence": "unresolved", "basis": "lecture", "explanation": "An epidural hematoma is possible after a road traffic collision, but post-traumatic unconsciousness alone does not distinguish it from subdural bleeding, contusion or other traumatic brain injury. The original entry gives no localizing CT appearance.", "evidence": {"title": "L26 (CBL) CNS Radiology  (1)", "sourceId": "1G45Gk2A6tw8TkfUa2k1fcqXXaunq2L5t", "page": 6, "unit": "page", "quote": "Acute epidural hematoma (lens shape and don’t cross the suture lines)", "url": "https://drive.google.com/file/d/1G45Gk2A6tw8TkfUa2k1fcqXXaunq2L5t/view#page=6", "cohortLabel": "MED444 teaching notes", "sourceSha256": "08d66f0fbdba78cf48e05ba1ce7a4a30223dd76f857aee28e1a83cc00e4b1002", "relation": "direct", "image": "lecture-media/radiology-final-review/1G45Gk2A6tw8TkfUa2k1fcqXXaunq2L5t-p06.jpg"}, "references": [{"title": "ACR · Head Trauma", "url": "https://acsearch.acr.org/docs/69481/Narrative"}]}, "ungradedReason": "The original question or options do not establish one usable answer."},
    "batch-radiology-final-433-q032": {"review": {"answers": ["B"], "confidence": "supported", "basis": "lecture", "explanation": "FLAIR suppresses the bright signal of free CSF while edema in brain tissue usually remains hyperintense. Ventricles and simple CSF collections therefore appear relatively dark.", "evidence": {"title": "L26 (CBL) CNS Radiology  (1)", "sourceId": "1G45Gk2A6tw8TkfUa2k1fcqXXaunq2L5t", "page": 2, "unit": "page", "quote": "T1: fluid is dark", "url": "https://drive.google.com/file/d/1G45Gk2A6tw8TkfUa2k1fcqXXaunq2L5t/view#page=2", "cohortLabel": "MED444 teaching notes", "sourceSha256": "08d66f0fbdba78cf48e05ba1ce7a4a30223dd76f857aee28e1a83cc00e4b1002", "relation": "direct", "image": "lecture-media/radiology-final-review/1G45Gk2A6tw8TkfUa2k1fcqXXaunq2L5t-p02.jpg"}}},
    "batch-radiology-final-432-q018": {"review": {"answers": ["A"], "confidence": "supported", "basis": "lecture", "explanation": "FLAIR suppresses the bright signal of free CSF while edema in brain tissue usually remains hyperintense. Ventricles and simple CSF collections therefore appear relatively dark.", "evidence": {"title": "L26 (CBL) CNS Radiology  (1)", "sourceId": "1G45Gk2A6tw8TkfUa2k1fcqXXaunq2L5t", "page": 2, "unit": "page", "quote": "T1: fluid is dark", "url": "https://drive.google.com/file/d/1G45Gk2A6tw8TkfUa2k1fcqXXaunq2L5t/view#page=2", "cohortLabel": "MED444 teaching notes", "sourceSha256": "08d66f0fbdba78cf48e05ba1ce7a4a30223dd76f857aee28e1a83cc00e4b1002", "relation": "direct", "image": "lecture-media/radiology-final-review/1G45Gk2A6tw8TkfUa2k1fcqXXaunq2L5t-p02.jpg"}}},
    "batch-radiology-final-433-q033": {"review": {"answers": ["A"], "confidence": "supported", "basis": "concept", "explanation": "The right posterior cerebral artery supplies the medial occipital lobe, parts of the medial temporal lobe and portions of the thalamus. A right-sided lesion there explains a left homonymous field deficit.", "references": [{"title": "ACR · Orbits, Vision, and Visual Loss", "url": "https://acsearch.acr.org/list/TopicNarrativePdf?topicId=361"}]}},
