    "batch-radiology-final-433-q035": {"review": {"answers": ["D"], "confidence": "supported", "basis": "concept", "explanation": "Central depressions of the vertebral endplates produce H-shaped vertebrae. Recurrent endplate infarcts make this a classic clue to sickle cell disease.", "references": [{"title": "Original pediatric cohort · Sickle Cell Bone Disease and Imaging", "url": "https://pubmed.ncbi.nlm.nih.gov/35904681/"}]}},
