    "batch-radiology-final-431-q050": {"review": {"answers": ["D"], "confidence": "supported", "basis": "concept", "explanation": "Severe anemia with back and hip pain fits a vaso-occlusive bone complication such as infarction or femoral head osteonecrosis. History and hemoglobin testing establish sickle cell disease; a plain film by itself cannot.", "references": [{"title": "GeneReviews · Sickle Cell Disease", "url": "https://www.ncbi.nlm.nih.gov/books/NBK1377/"}, {"title": "Original pediatric cohort · Sickle Cell Bone Disease and Imaging", "url": "https://pubmed.ncbi.nlm.nih.gov/35904681/"}]}},
    "batch-radiology-final-433-q037": {"review": {"answers": [], "confidence": "unresolved", "basis": "lecture", "explanation": "An aggressive predominantly lytic lesion may be photopenic on a bone scan when little osteoblastic repair occurs. Anaplastic histology alone does not predict tracer uptake, and some metastases are hot or mixed.", "evidence": {"title": "L27 Nuclear medicine in oncology", "sourceId": "1gtqxnEr7g3JmC2779aHuQ6N4gBoYKL-p", "page": 3, "unit": "page", "quote": "Bone metastasis; breast cancer, prostate cancer.", "url": "https://drive.google.com/file/d/1gtqxnEr7g3JmC2779aHuQ6N4gBoYKL-p/view#page=3", "cohortLabel": "MED444 teaching notes", "sourceSha256": "90265ab48690ae2a3001dc755fc42b4b00106c845ed66994de2269fd892ca446", "relation": "direct", "image": "lecture-media/radiology-final-review/1gtqxnEr7g3JmC2779aHuQ6N4gBoYKL-p-p03.jpg"}, "references": [{"title": "EANM · Practice Guidelines for Bone Scintigraphy", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC4932135/"}]}, "ungradedReason": "The original question or options do not establish one usable answer."},
