    "batch-radiology-final-433-q041": {"review": {"answers": [], "confidence": "unresolved", "basis": "lecture", "explanation": "Beta emitters are used in several radionuclide therapies. Selected therapies also use alpha emitters. Gamma emission may accompany a therapeutic isotope but is usually used for imaging. The question offers several nonspecific choices and the source gives two letters.", "evidence": {"title": "L27 Nuclear medicine in oncology", "sourceId": "1gtqxnEr7g3JmC2779aHuQ6N4gBoYKL-p", "page": 6, "unit": "page", "quote": "Iodine-131 is a beta minus emitter", "url": "https://drive.google.com/file/d/1gtqxnEr7g3JmC2779aHuQ6N4gBoYKL-p/view#page=6", "cohortLabel": "MED444 teaching notes", "sourceSha256": "90265ab48690ae2a3001dc755fc42b4b00106c845ed66994de2269fd892ca446", "relation": "direct", "image": "lecture-media/radiology-final-review/1gtqxnEr7g3JmC2779aHuQ6N4gBoYKL-p-p06.jpg"}, "references": [{"title": "EANM · Radionuclide Therapy Guidelines", "url": "https://eanm.org/publications/guidelines/overview/radionuclide-therapy/"}]}, "ungradedReason": "The original question or options do not establish one usable answer."},
    "batch-radiology-final-433-q042": {"review": {"answers": [], "confidence": "unresolved", "basis": "concept", "explanation": "The liver and spleen are the principal sites of extramedullary hematopoiesis. Bone marrow itself is medullary. None of the offered groups gives the standard liver-and-spleen pairing.", "references": [{"title": "Thalassaemia International Federation · Extramedullary Haematopoiesis", "url": "https://www.ncbi.nlm.nih.gov/books/NBK599494/"}]}, "ungradedReason": "The original question or options do not establish one usable answer."},
    "batch-radiology-final-432-q001": {"review": {"answers": ["B"], "confidence": "supported", "basis": "concept", "explanation": "One metacarpal is shortened compared with the opposite hand. This can follow premature closure of the physis after an injury. The late film demonstrates growth disturbance rather than the acute fracture line.", "references": [{"title": "Pediatric physeal injuries and the Salter–Harris classification", "url": "https://pubmed.ncbi.nlm.nih.gov/27206505/"}]}},
