    "batch-radiology-final-432-q010": {"review": {"answers": ["B"], "confidence": "supported", "basis": "concept", "explanation": "Diffuse osteoblastic metastases in breast cancer can cause a skeletal superscan, with intense bone activity and faint kidneys. Prostate carcinoma and metabolic bone disorders can produce the same pattern.", "references": [{"title": "EANM · Practice Guidelines for Bone Scintigraphy", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC4932135/"}]}},
    "batch-radiology-final-432-q012": {"review": {"answers": [], "confidence": "unresolved", "basis": "concept", "explanation": "Ultrasound can evaluate superficial soft tissues, including accessible ligaments. Both the specific ligament choice and the broader soft-tissue choice are true without a more specific question.", "references": [{"title": "ACR · Acute Elbow and Forearm Pain", "url": "https://acsearch.acr.org/list/TopicNarrativePdf?topicId=335"}]}, "ungradedReason": "The original question or options do not establish one usable answer."},
    "batch-radiology-final-432-q014": {"review": {"answers": ["B"], "confidence": "supported", "basis": "lecture", "explanation": "Sestamibi retention depends in part on mitochondrial content. Predominantly clear chief-cell adenomas can show weaker retention than oxyphil-rich lesions and may yield a false-negative result.", "evidence": {"title": "L22 (CBL) Endocrine Radiology", "sourceId": "1WddjUab6yD4K9z_VIUXWa1_Micvsa2jM", "page": 15, "unit": "page", "quote": "Clear Chief cells: responsible for PTH production", "url": "https://drive.google.com/file/d/1WddjUab6yD4K9z_VIUXWa1_Micvsa2jM/view#page=15", "cohortLabel": "MED444 teaching notes", "sourceSha256": "85399286a691d14733fdea568858d5920f5e5d66a8e9bf667553160752ac1f34", "relation": "direct", "image": "lecture-media/radiology-final-review/1WddjUab6yD4K9z_VIUXWa1_Micvsa2jM-p15.jpg"}, "references": [{"title": "EANM · Guidelines for Parathyroid Imaging", "url": "https://pubmed.ncbi.nlm.nih.gov/33839893/"}]}},
    "batch-radiology-final-432-q017": {"review": {"answers": ["C"], "confidence": "supported", "basis": "lecture", "explanation": "Delayed focal uptake below the right thyroid region in a patient with hypercalcemia and renal stones supports an inferior right parathyroid adenoma. The wording “right lower lobe” refers to its position relative to the thyroid.", "evidence": {"title": "L22 (CBL) Endocrine Radiology", "sourceId": "1WddjUab6yD4K9z_VIUXWa1_Micvsa2jM", "page": 12, "unit": "page", "quote": "Most commonly used for parathyroid imaging", "url": "https://drive.google.com/file/d/1WddjUab6yD4K9z_VIUXWa1_Micvsa2jM/view#page=12", "cohortLabel": "MED444 teaching notes", "sourceSha256": "85399286a691d14733fdea568858d5920f5e5d66a8e9bf667553160752ac1f34", "relation": "direct", "image": "lecture-media/radiology-final-review/1WddjUab6yD4K9z_VIUXWa1_Micvsa2jM-p12.jpg"}, "references": [{"title": "EANM · Guidelines for Parathyroid Imaging", "url": "https://pubmed.ncbi.nlm.nih.gov/33839893/"}]}},
    "batch-radiology-final-432-q019": {"review": {"answers": ["A"], "confidence": "supported", "basis": "concept", "explanation": "The enhancing sellar mass extends above the sella toward the optic chiasm, which can explain the visual deficit. A pituitary macroadenoma is the best choice.", "references": [{"title": "ACR · Neuroendocrine Imaging", "url": "https://acsearch.acr.org/docs/69485/Narrative/"}]}},
    "batch-radiology-final-432-q020": {"review": {"answers": ["B"], "confidence": "supported", "basis": "concept", "explanation": "The projection emphasizes the circle of Willis and its branches while suppressing much of the background. This resembles a time-of-flight MR angiogram.", "references": [{"title": "ACR · Cerebrovascular Disease", "url": "https://acsearch.acr.org/docs/69478/Narrative"}]}},
    "batch-radiology-final-432-q021": {"review": {"answers": ["D"], "confidence": "supported", "basis": "lecture", "explanation": "The arrow highlights a focal periventricular white-matter lesion. Among the offered diagnoses, demyelination fits the patient's age and the depicted location best. One image is insufficient to establish dissemination in space or time.", "evidence": {"title": "L26 (CBL) CNS Radiology  (1)", "sourceId": "1G45Gk2A6tw8TkfUa2k1fcqXXaunq2L5t", "page": 13, "unit": "page", "quote": "multiple lesions in the periventricular and subcortical white matter", "url": "https://drive.google.com/file/d/1G45Gk2A6tw8TkfUa2k1fcqXXaunq2L5t/view#page=13", "cohortLabel": "MED444 teaching notes", "sourceSha256": "08d66f0fbdba78cf48e05ba1ce7a4a30223dd76f857aee28e1a83cc00e4b1002", "relation": "direct", "image": "lecture-media/radiology-final-review/1G45Gk2A6tw8TkfUa2k1fcqXXaunq2L5t-p13.jpg"}}},
