    "batch-radiology-final-431-q031": {"review": {"answers": [], "confidence": "unresolved", "basis": "lecture", "explanation": "This image shows a parasagittal chronic lesion in the anterior cerebral artery distribution, which affects the opposite leg more than the arm. Without a clear side marker in this reproduction, the exact right-sided deficit in the key is not independently established.", "evidence": {"title": "L26 (CBL) CNS Radiology  (1)", "sourceId": "1G45Gk2A6tw8TkfUa2k1fcqXXaunq2L5t", "page": 19, "unit": "page", "quote": "Chronic ACA infarct", "url": "https://drive.google.com/file/d/1G45Gk2A6tw8TkfUa2k1fcqXXaunq2L5t/view#page=19", "cohortLabel": "MED444 teaching notes", "sourceSha256": "08d66f0fbdba78cf48e05ba1ce7a4a30223dd76f857aee28e1a83cc00e4b1002", "relation": "direct", "image": "lecture-media/radiology-final-review/1G45Gk2A6tw8TkfUa2k1fcqXXaunq2L5t-p19.jpg"}}, "ungradedReason": "The original question or options do not establish one usable answer."},
    "batch-radiology-final-432-q025": {"review": {"answers": ["A"], "confidence": "supported", "basis": "lecture", "explanation": "Fluorine-18 FDG PET/CT is widely used to stage and restage metabolically active cancers. Tracer selection depends on tumor biology, so it is not best for every malignancy.", "evidence": {"title": "L27 Nuclear medicine in oncology", "sourceId": "1gtqxnEr7g3JmC2779aHuQ6N4gBoYKL-p", "page": 5, "unit": "page", "quote": "Pretty good tracer for malignancy, but not specific", "url": "https://drive.google.com/file/d/1gtqxnEr7g3JmC2779aHuQ6N4gBoYKL-p/view#page=5", "cohortLabel": "MED444 teaching notes", "sourceSha256": "90265ab48690ae2a3001dc755fc42b4b00106c845ed66994de2269fd892ca446", "relation": "direct", "image": "lecture-media/radiology-final-review/1gtqxnEr7g3JmC2779aHuQ6N4gBoYKL-p-p05.jpg"}, "references": [{"title": "L27 Nuclear medicine in oncology · MED444 PDF p. 4", "url": "https://drive.google.com/file/d/1gtqxnEr7g3JmC2779aHuQ6N4gBoYKL-p/view#page=4"}]}},
    "batch-radiology-final-431-q042": {"review": {"answers": ["C"], "confidence": "supported", "basis": "lecture", "explanation": "Fluorine-18 FDG PET/CT is widely used to stage and restage metabolically active cancers. Tracer selection depends on tumor biology, so it is not best for every malignancy.", "evidence": {"title": "L27 Nuclear medicine in oncology", "sourceId": "1gtqxnEr7g3JmC2779aHuQ6N4gBoYKL-p", "page": 5, "unit": "page", "quote": "Pretty good tracer for malignancy, but not specific", "url": "https://drive.google.com/file/d/1gtqxnEr7g3JmC2779aHuQ6N4gBoYKL-p/view#page=5", "cohortLabel": "MED444 teaching notes", "sourceSha256": "90265ab48690ae2a3001dc755fc42b4b00106c845ed66994de2269fd892ca446", "relation": "direct", "image": "lecture-media/radiology-final-review/1gtqxnEr7g3JmC2779aHuQ6N4gBoYKL-p-p05.jpg"}, "references": [{"title": "L27 Nuclear medicine in oncology · MED444 PDF p. 4", "url": "https://drive.google.com/file/d/1gtqxnEr7g3JmC2779aHuQ6N4gBoYKL-p/view#page=4"}]}},
    "batch-radiology-final-432-q030": {"review": {"answers": [], "confidence": "unresolved", "basis": "concept", "explanation": "Octreotide uptake demonstrates somatostatin-receptor activity. Physiologic organs also take up tracer, and the displayed planar pattern without anatomic localization or biochemical context cannot distinguish paraganglioma, insulinoma or another receptor-expressing tumor.", "references": [{"title": "SNMMI and EANM · SSTR PET in Neuroendocrine Tumors", "url": "https://pubmed.ncbi.nlm.nih.gov/36725249/"}]}, "ungradedReason": "The original question or options do not establish one usable answer."},
